export function renderDigest(user, articles) {
  const items = articles.map(function (a) {
    return `  <li class="art"><a href="${a.url}">${escapeHtml(a.title)}</a> <span>${a.minutes} min</span></li>`;
  }).join("\n");
  return `<div class="digest">\n<h2>Hi ${escapeHtml(user)}</h2>\n<ul>\n${items}\n</ul>\n<p>${articles.length} article(s)</p>\n</div>`;
