result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/digest.golden.test.mjs", "content": "// Snapshot (golden) tests for renderDigest.
//
// Workflow: goldens are committed. If output changes intentionally, run
//   UPDATE_GOLDEN=1 node --test digest.golden.test.mjs
// review the printed changed files + `git diff golden/`, and commit.
//
// Comparison rule: only trailing newline(s) are normalized. Everything else
// must match byte-for-byte.

import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { renderDigest } from "./digest.mjs";
import * as cases from "./cases.mjs";

const GOLDEN_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), "golden");
const UPDATE = process.env.UPDATE_GOLDEN === "1";

fs.mkdirSync(GOLDEN_DIR, { recursive: true });

// ---------- tiny LCS-based line diff ----------

function diffLines(expected, actual) {
  const a = expected.split("\n");
  const b = actual.split("\n");
  // LCS table (fine for digest-sized outputs)
  const dp = Array.from({ length: a.length + 1 }, () => new Uint32Array(b.length + 1));
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);

  const out = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) { out.push([" ", a[i]]); i++; j++; }
    else if (dp[i + 1][j] >= dp[i][j + 1]) { out.push(["-", a[i++]]); }
    else { out.push(["+", b[j++]]); }
  }
  while (i < a.length) out.push(["-", a[i++]]);
  while (j < b.length) out.push(["+", b[j++]]);
  return out;
}

function formatDiff(expected, actual) {
  return [
    "line-by-line diff (- golden, + actual):",
    ...diffLines(expected, actual).map(([m, l]) => `${m} ${JSON.stringify(l)}`),
  ].join("\n");
}

// ---------- normalization: trailing newline ONLY ----------

function normalizeTrailingNewline(s) {
  return s.replace(/\n+$/, "");
}

// ---------- snapshot tests, one per case ----------

for (const [name, { user, articles }] of Object.entries(cases)) {
  test(`golden: ${name}`, () => {
    const html = renderDigest(user, articles);
    const file = path.join(GOLDEN_DIR, `${name}.html`);

    if (UPDATE) {
      let status = "created";
      if (fs.existsSync(file)) {
        const old = normalizeTrailingNewline(fs.readFileSync(file, "utf8"));
        status = old === normalizeTrailingNewline(html) ? "unchanged" : "CHANGED";
      }
      fs.writeFileSync(file, html.endsWith("\n") ? html : html + "\n");
      console.log(`[update-golden] ${status.padEnd(9)} ${path.relative(process.cwd(), file)}`);
      return; // regen run passes; review via git diff before committing
    }

    assert.ok(fs.existsSync(file), `missing golden: ${file} — run UPDATE_GOLDEN=1 node --test`);
    const golden = normalizeTrailingNewline(fs.readFileSync(file, "utf8"));
    const actual = normalizeTrailingNewline(html);
    assert.equal(actual, golden, `rendered digest differs from golden\n${formatDiff(golden, actual)}`);
  });
}

// ---------- safety net #1: href attributes survive byte-exact ----------
// URLs are intentionally NOT passed through escapeHtml; this pins that down.

for (const [name, { user, articles }] of Object.entries(cases)) {
  test(`href byte-exact: ${name}`, () => {
    const html = renderDigest(user, articles);
    for (const a of articles) {
      assert.ok(
        html.includes(`href="${a.url}"`),
        `href attribute for ${a.url} was mangled in case "${name}"\n${formatDiff(
          articles.map((x) => `href="${x.url}"`).join("\n"),
          (html.match(/href="[^"]*"/g) ?? []).join("\n"),
        )}`,
      );
    }
  });
}

// ---------- safety net #2 (independent of snapshots): goldens contain no
// unescaped <script anywhere. Protects against blindly accepting a bad regen.

test("goldens contain no UNescaped <script", () => {
  const offenders = [];
  for (const f of fs.readdirSync(GOLDEN_DIR).filter((f) => f.endsWith(".html"))) {
    const content = fs.readFileSync(path.join(GOLDEN_DIR, f), "utf8");
    if (content.includes("<script")) offenders.push(f);
  }
  assert.deepEqual(
    offenders,
    [],
    `unescaped <script found in golden files (escapeHtml broken? bad regen accepted?):\n` +
      offenders.map((f) => `  ${f}`).join("\n"),
  );
});
"})
